am brand.", "founded_year": "1959", "employee_count": "1000", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Veteran-owned", "Family-owned"]}'::jsonb, updated_at=now() WHERE slug='alamance-foods-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Alameda Food Service, a family-owned wholesale restaurant food supplier, was founded in 1977 and is headquartered in Las Vegas, Nevada. The company began as a distributor committed to delivering quality and value to food service operators across the western United States.

The company operates a full-service distribution center in Las Vegas, providing product delivery and inventory management with temperature-controlled cold storage. Its logistics network supplies fresh meats, produce, dairy, seafood, grocery items, tortillas, oils, paper disposables, janitorial supplies, and frozen foods to professional kitchens.

