UPDATE companies SET description='Approved Sheet Metal operates from Hudson, New Hampshire. The company was formed in 2020 by experienced sheet metal fabrication leaders who wanted to support American manufacturing by improving how parts are designed, made, and delivered.

The shop specializes in custom precision prototype and low-volume production sheet metal fabrication. Core processes include laser cutting, forming, welding, hardware insertion, powder coating, silk screening, and a range of finishing options from mill finish to Class A cosmetic. The facility handles quantities from a single piece up to 5,000 parts, turning thousands of unique part numbers each month.

Customers are primarily product developers and buyers across a range of industries who need fast, precise sheet metal parts. The company emphasizes support for American manufacturing and works with clients nationwide on projects such as enclosures, weldments, brackets, RF/EMI shields, chassis, cabinets, and 19-inch rack components.

The founders built the company on speed and technology: quotes are returned within hours, flat laser-cut parts can ship the same day if ordered by 10 a.m. EST, and formed prototypes typically deliver in two to five days. The operation is ISO 9001:2015 certified and ITAR registered, and runs on a custom ERP with real-time material inventory to keep lead times short.', certifications=ARRAY['ISO 9001:2015','ITAR']::text[], profile='{"capabilities": ["Laser cutting", "Forming / bending", "Welding", "Hardware insertion", "Powder coating", "Silk screening", "Finishing (mill finish to Class A cosmetic)", "Design for Manufacturing (DFM) review", "CAD file support (DXF, STEP, IGES, SLDPRT, PDF)", "Prototype sheet metal fabrication", "Low-volume production (up to 5,000 parts)", "Same-day flat part shipping", "Assembly (enclosures, weldments, chassis, cabinets)", "RF/EMI shielding fabrication"], "industries": [], "materials": ["Steel", "Aluminum", "Stainless steel"], "equipment": [], "volume": "Quantity 1 to 5,000 parts", "lead_time": "2\u20135 days for prototypes; same-day shipping for flat parts ordered by 10 a.m. EST; 5\u201310 days for formed parts with hardware", "tolerances": "\u00b10.005\u2033\u2013\u00b10.010\u2033 on laser-cut profiles; \u00b10.010\u2033 flatness on composite parts", "built_on": ["Same-day shipping on flat parts ordered by 10 a.m. EST", "Quote turnaround within hours", "Prototype delivery in 2\u20135 days", "ISO 9001:2015 certified and ITAR registered", "Custom ERP with real-time material inventory and job scheduling"], "facts_used": ["Headquarters: Hudson, New Hampshire -> db", "Founded: 2020 -> /about", "Company description: American sheet metal fabricator of custom precision prototype and low volume production -> /", "Certifications: ISO 9001:2015, ITAR -> /, /about", "Capabilities: laser cutting, forming, welding, hardware insertion, powder coating, silk screening, finishing -> /", "Volume range: Quantity 1 to 5,000 parts -> /", "Lead times: 2-5 days prototypes, same-day flat parts, 5-10 days formed parts -> /", "Tolerances: \u00b10.005\u20130.010 in laser, \u00b10.010 in flatness -> /", "Materials: steel, aluminum, stainless steel -> /", "Team members listed -> /about", "Acquisitions: Technical Machine Components, Nashua Fabrication -> /about", "Custom ERP with real-time inventory -> /", "DFM review and CAD file support -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Approved Sheet metal (ASM) is an American sheet metal fabricator of custom precision prototype and low volume production sheet metal fabricated parts.", "founded_year": "2020", "employee_count": "", "cage_code": "", "min_order": "1", "export_compliance": ["ITAR registered"], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='approved-sheet-metal' AND approved AND profile IS NULL;
UPDATE companies SET description='Architectural System Fabricators LLC operates from a facility on Industrial Drive in Southington, Connecticut. The company was founded in 2019 by Adam, who grew up in construction working alongside his father before expanding into commercial metalwork and investing in advanced machinery for his own projects. Recognizing a gap in the market for reliable, high-quality architectural metal fabrication, he established ASF to focus on precision, speed, and customer collaboration.

The shop specializes exclusively in architectural metalwork — not general steel fabrication — producing custom ACM panels, brake-formed components, CNC-routed designs, and long-folded profiles up to 20 feet. Core processes include brake forming, CNC routing, laser cutting, punching, in-house coil processing, welding, folding, shearing, and both liquid and powder coating. Equipment highlights include Connecticut''s only long-folding machine, advanced CNC routers, and high-precision laser cutters. The team brings over 55 years of combined architectural metal fabrication experience.

ASF serves architects, contractors, and construction firms on commercial, institutional, and industrial projects across the United States, with a regional focus on Fairfield County, southern Connecticut, and New England. Past work includes ACM panels and brake-formed trim for the Greenwich Residence, aluminum soffit panels for the Plainville School, and 100,000 square feet of custom louver blades for a single project. The company also fabricated components for the CJ Huang Recreation Center and has worked with Laminators Inc.

The company differentiates itself through its architectural-only focus, in-house coil processing, and the long-folding capability unique in Connecticut. It emphasizes design support, turning concepts into fabrication-ready drawings, and nationwide shipping with secure crating from single pallets to full truckloads.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom architectural metal fabrication", "Brake forming", "CNC routing", "Laser cutting", "Punching", "In-house coil processing", "Long-folding (over 20 feet)", "Welding", "Folding", "Shearing", "Custom profiles", "ACM panel fabrication", "Fiber cement panel fabrication", "Roof panel fabrication", "Wall panel fabrication", "Liquid coating", "Powder coating", "Drafting and design support"], "industries": ["Architects", "Contractors", "Construction firms", "Commercial construction", "Institutional construction", "Industrial construction", "Architectural metals and panel systems"], "materials": ["Aluminum", "Aluminum Composite Material (ACM)", "Copper", "Stainless Steel", "Zinc", "Mild Steel", "High-Density Fiber Cement", "Phenolic", "Fiber cement panels"], "equipment": ["Connecticut''s only long-folding machine", "Advanced CNC routers", "High-precision laser cutters", "Coil processors", "Punching equipment"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Connecticut''s only long-folding machine for metal pieces over 20 feet", "In-house coil processing", "55+ years combined architectural metal fabrication expertise", "Nationwide shipping with secure crating", "Design and drafting support for fabrication-ready drawings"], "facts_used": ["Founded 2019 by Adam -> /about-us", "Headquarters Southington, CT -> /, /about-us, /capabilities", "55+ years combined team experience -> /, /capabilities", "Connecticut''s only long-folding machine -> /, /capabilities", "In-house coil processing -> /capabilities, /about-us FAQ", "Materials: aluminum, ACM, copper, stainless steel, zinc, mild steel,